/**
 * Static diagnostic test catalog.
 *
 * Every test here is HAND-AUTHORED and never generated by a model. This is the
 * deterministic counterpart to the model's hypotheses: the model may only
 * classify a fault into the fixed `FaultCode` vocabulary, and each test below
 * references those same codes, so a test result can deterministically raise or
 * lower a specific hypothesis (see `interpret`).
 *
 * The physical-safety metadata on each test (`riskLevel`, `reversibility`,
 * `requiresDisassembly`, `requiresPowerManipulation`, `difficulty`) is what the
 * deterministic selector ranks and gates on. Nothing in this file decides which
 * test is offered — that is the selector's job — and nothing here authors a
 * physical repair procedure. These are low-commitment diagnostic checks a user
 * can safely perform (or, for the gated ones, explicitly must NOT be walked
 * through automatically).
 *
 * Two tests are deliberately unsafe-to-auto-offer and exist to prove the gate:
 *   - `reseat_internal_module` requires disassembly;
 *   - `measure_adapter_output` requires power manipulation and is high risk.
 * The selector must never auto-select either (see diagnosticTestSelector.ts).
 */

import {
  DiagnosticTest,
  FaultCode,
  HypothesisEffect,
  TestAnswer,
  TestApplicabilityContext
} from '../../types/diagnostic';

/** True when the current hypotheses include any of `codes`. */
const targets = (ctx: TestApplicabilityContext, ...codes: FaultCode[]): boolean =>
  codes.some((code) => ctx.hypothesisCodes.includes(code));

/** Small helper to build an effect with a readable note. */
const effect = (code: FaultCode, delta: number, note: string): HypothesisEffect => ({
  code,
  delta,
  note
});

